<template>
  <div class="table-container">
    <div class="b30-list">
      <div class="card-grid" :style="gridStyle">
        <slot 
          v-for="(item, index) in b30List" 
          :key="index"
          :cardData="item"
          :index="index"
        >
          <b30Card :chart-info="item" />
        </slot>
      </div>
      <div class="fixed-left-text">
        RKS {{ rksL[0] }} ({{ rksL[1] }})
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted, computed } from 'vue'
import b30Card from '../../components/cards/b30Card.vue'
import { getB30 } from '../../api/levels.js'

const b30List = ref(null)
const rksL = ref([])

onMounted(async () => {
  try {
    const [b30Data,rksLData] = await getB30()
    b30List.value = b30Data
    rksL.value = rksLData
  } catch (error) {
    console.error('B30加载失败：', error)
  }
})

const props = defineProps({
  columns: {
    type: Number,
    default: 3
  },
  gap: {
    type: Number,
    default: 0.2
  },
  gridWidth: {
    type: [Number, String],
    default: '100%'
  }
})

const gridStyle = computed(() => {
  return {
    width: typeof props.gridWidth === 'number' ? `${props.gridWidth}px` : props.gridWidth,
    '--column-count': props.columns,
    '--gap-rem': `${props.gap}rem`
  }
})
</script>

<style scoped>
.b30-list {
  margin-top: 0.2rem;
}

.fixed-left-text {
  left: 50%;
  top: 10%;
  text-align: center;
  padding: 0.16rem 0.1rem;
  color: var(--color-text-sub);
  font-size: 0.2rem;
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(var(--column-count), 1fr);
  gap: var(--gap-rem);
  box-sizing: border-box;
  margin: 0 auto;
  user-select: none;
}

.card-grid > * {
  width: 100% !important;
  flex-shrink: 0;
  box-sizing: border-box;
}
</style>